Self-Service Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(api_gateway, "API Gateway", "API Gateway")

Container_Boundary(self_service_portal, "Self-Service Portal") {
    Component(web_ui_and_accessibility_layer, "Web UI and Accessibility Layer", "React with WCAG 2.1 AA accessibility standards and axe-core", "Provides the user interface for library patrons, librarians, and administrators with strict accessibility and client-side error boundaries.")
    Component(session_and_authentication_handler, "Session and Authentication Handler", "OAuth2/OIDC with PKCE, httpOnly/secure/SameSite=Strict cookies", "Manages user authentication, secure session cookies, and Content Security Policy (CSP) headers.")
    Component(api_proxy_client, "API Proxy Client", "HTTPS / TLS 1.3 with mTLS via SPIFFE/SPIRE", "Routes authenticated user actions and requests from the portal to the downstream API Gateway.")
}

Rel(web_ui_and_accessibility_layer, session_and_authentication_handler, "Validates session and authenticates user actions")
Rel(session_and_authentication_handler, api_proxy_client, "Passes authenticated requests")
Rel(api_proxy_client, api_gateway, "Routes requests securely", "mTLS via SPIFFE/SPIRE")
@enduml

Search Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(search_container, "Search Container") {
    Component(Search_Indexer, "Search Indexer", "Elasticsearch / OpenSearch", "Horizontally scalable search engine for low-latency search (<800 ms R-05 requirement) and asynchronous Change-Data-Capture (CDC) data ingestion.")
    Component(Search_API_Handler, "Search API Handler", "OpenSearch REST API / mTLS", "Receives routed search requests from the API Gateway via mTLS and enforces document-level access controls.")
    Component(Telemetry_Sidecar, "Telemetry Sidecar", "Fluentbit", "Asynchronous sidecar for routing user telemetry and piping metrics/audit logs without impacting disk I/O.")
}

Rel(Search_API_Handler, Search_Indexer, "Queries and retrieves catalog data")
Rel(Search_Indexer, Telemetry_Sidecar, "Pipes metrics, audit logs, and routes user telemetry")

@enduml

User Analytics & Feedback Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the User Analytics & Feedback Container container

Container_Boundary(user_analytics_feedback_container, "User Analytics & Feedback Container") {
    Component(fluentbit_sidecars, "Fluentbit sidecars", "Edge log collection", "Ingests telemetry via asynchronous message queues with schema validation.")
    Component(kafka_ingestion_consumers, "Kafka ingestion consumers", "Kafka", "Handles asynchronous telemetry ingestion.")
    Component(dead_letter_queue_dlq, "Dead Letter Queue (DLQ)", "Messaging Queue", "Manages failed message delivery and error handling.")
}

Rel(fluentbit_sidecars, kafka_ingestion_consumers, "Ingests telemetry via asynchronous message queues with schema validation.", "Asynchronous / Message Queue")
Rel(kafka_ingestion_consumers, dead_letter_queue_dlq, "Routes failed ingestion messages.", "Messaging")

@enduml
